// src/app/[locale]/our-collections/the-borgia-tonchinensis-collection/_data/descriptions.ts
//
// DVN's descriptive layer for the Borgia Tonchinensis manuscripts.
//
// HAND-MAINTAINED — unlike VaticanBorgiaMetadata.ts, which the fetch script
// regenerates. The Vatican catalogues this whole fond as shelfmark-only
// records: no titles, no dates, no summaries. Everything a reader needs in
// order to tell one volume from another therefore has to be written here.
//
// Entries are keyed by shelfmark and every field is optional, so the collection
// ships browsable today and improves one record at a time. An item with no
// entry falls back to its shelfmark, which is exactly what the Vatican shows.
//
// genre, scripts and century are the fields the browse sidebar will filter on
// once enough records carry them; until then the grid offers search only.
//
// PROVENANCE — titles and abstracts came from different places and are at
// different stages. Do not treat them as one body of text.
//
// TITLES (all 41, both languages) — DVN's own cataloguing, from "Borgia
// Tonchinensis abstract (2).xlsx" (Drive id 1L6jmevfJnsypB3-eP8kicegiYQDp3YCm).
// Thirty-seven English titles came straight from its column E. Three were
// recovered from elsewhere in the workbook, each corroborated by the item's
// Vietnamese title: Borg.tonch.12 from a stray column F, Borg.tonch.13 from the
// row above, Borg.tonch.20 from a parenthetical in its own abstract. One —
// Borg.tonch.18, "A Book of Novena Prayers" — is NOT the cataloguer's wording;
// no English for it exists in the workbook, so it was rendered to the house
// style of the other forty. Replace it with theirs when they supply it.
//
// ABSTRACTS — unchanged, and a stage behind the titles:
//   - vi: DVN's cataloguer, verbatim from the FIRST spreadsheet.
//   - en: MACHINE TRANSLATION of that Vietnamese, generated by an LLM and not
//     checked by anyone who reads both languages. Proper names, Latin and
//     Portuguese titles, dates and page counts were carried across unchanged,
//     but the wording is not a human translator's and should be reviewed
//     before it is quoted or cited. Replace an entry's `en` as it is checked.
//
// The revised spreadsheet's abstract columns were deliberately NOT imported:
// two long English entries had overflowed down the column, truncating their own
// cell and overwriting the neighbour's, leaving twelve items describing the
// wrong manuscript. Titles were taken from it because those are sound; the
// abstracts wait for a corrected sheet.
//
// House style for whoever fills the rest in:
//   - title: what the volume is, not a catalogue heading.
//   - summary: what it contains, who wrote or copied it, and why a researcher
//     would open it.
//   - en: add alongside vi when a translation exists; until then English
//     readers are shown the Vietnamese, labelled as such.
//   - scripts: as written on the page — "Quốc ngữ", "Nôm", "Latin",
//     "Portuguese", "Chinese". A volume may mix several.

export interface BorgiaDescription {
  /** English is optional: DVN catalogued this fond in Vietnamese first, and a
      page falls back to the Vietnamese rather than showing a bare shelfmark. */
  title?: { vi: string; en?: string };
  summary?: { vi: string; en?: string };
  /** chronicle | catechism | prayer book | dictionary | correspondence | … */
  genre?: string;
  /** Scripts and languages present in the volume. */
  scripts?: string[];
  /** "17th" | "18th" | "19th" */
  century?: string;
}

/** Keyed by Vatican shelfmark. An empty object means "not yet catalogued". */
